namespace sv_223a8a21b127483ba4ad363146c5d00d.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

/// <summary>
/// Mutable form model for building the application across steps.
/// </summary>
public class JobApplicationFormModel
{
    public PersonalInfoModel Personal { get; set; } = new();
    public List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
    public List<ReferenceModel> References { get; set; } = new() { new ReferenceModel() };
    public string CoverLetter { get; set; } = string.Empty;

    public JobApplication ToRecord() => new(
        Personal.ToRecord(),
        new WorkHistory(WorkEntries.Select(w => w.ToRecord()).ToList()),
        References.Select(r => r.ToRecord()).ToList(),
        CoverLetter
    );
}

public class PersonalInfoModel
{
    public string FullName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string Address { get; set; } = string.Empty;

    public bool IsValid() =>
        !string.IsNullOrWhiteSpace(FullName) &&
        !string.IsNullOrWhiteSpace(Email) &&
        !string.IsNullOrWhiteSpace(Phone) &&
        !string.IsNullOrWhiteSpace(Address);

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = string.Empty;

    public bool IsValid() =>
        !string.IsNullOrWhiteSpace(Company) &&
        !string.IsNullOrWhiteSpace(Title) &&
        StartDate.HasValue;

    public WorkEntry ToRecord() => new(Company, Title, StartDate!.Value, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = string.Empty;
    public string Relationship { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;

    public bool IsValid() =>
        !string.IsNullOrWhiteSpace(Name) &&
        !string.IsNullOrWhiteSpace(Relationship) &&
        !string.IsNullOrWhiteSpace(Email) &&
        !string.IsNullOrWhiteSpace(Phone);

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

using sv_223a8a21b127483ba4ad363146c5d00d.Models;

namespace sv_223a8a21b127483ba4ad363146c5d00d.Services;

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_223a8a21b127483ba4ad363146c5d00d.Models;

namespace sv_223a8a21b127483ba4ad363146c5d00d.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(500); // Simulate network call
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(200); // Simulate network call
        return !string.IsNullOrWhiteSpace(email) &&
               email.Contains('@') &&
               email.Contains('.');
    }
}

