@namespace sv_223a8a21b127483ba4ad363146c5d00d.Components.Pages.Apply
@using sv_223a8a21b127483ba4ad363146c5d00d.Models

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-danger btn-sm remove-btn" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" @bind="Entry.Company" placeholder="Company name" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" @bind="Entry.Title" placeholder="Job title" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" @bind="Entry.StartDate" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="Entry.IsCurrent" /> Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" @bind="Entry.Description" rows="3" placeholder="Describe your responsibilities..."></textarea>
    </div>
</fieldset>

@code {
    [Parameter] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_223a8a21b127483ba4ad363146c5d00d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="0">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

