@using sv_223a8a21b127483ba4ad363146c5d00d.Models

<fieldset class="reference-form">
    <legend>Reference @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-danger btn-sm remove-btn" @onclick="OnRemove">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" class="form-control" @bind="Reference.Name" placeholder="Reference name" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" class="form-control" @bind="Reference.Relationship" placeholder="e.g., Former Manager" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" @bind="Reference.Email" placeholder="Email address" />
        </div>

        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" @bind="Reference.Phone" placeholder="Phone number" />
