@namespace sv_223a8a21b127483ba4ad363146c5d00d.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea"
                  @bind="CoverLetter" @bind:event="oninput"
                  rows="12" maxlength="@MaxLength"
                  placeholder="Tell us why you're a great fit for this role..."></textarea>
        <div class="character-count @(CoverLetter.Length > MaxLength ? "over-limit" : "")">
            @CoverLetter.Length / @MaxLength characters
        </div>
    </div>

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task HandleNext()
    {
        await CoverLetterChanged.InvokeAsync(CoverLetter);
        await OnNext.InvokeAsync();
    }
}

@namespace sv_223a8a21b127483ba4ad363146c5d00d.Components.Pages.Apply
@using sv_223a8a21b127483ba4ad363146c5d00d.Models

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h3>Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We'll be in touch soon.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-data">
                <dt>Name</dt><dd>@Model.Personal.FullName</dd>
                <dt>Email</dt><dd>@Model.Personal.Email</dd>
                <dt>Phone</dt><dd>@Model.Personal.Phone</dd>
                <dt>Address</dt><dd>@Model.Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in Model.WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="review-dates">
                        @entry.StartDate?.ToString("MMM yyyy") &mdash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var reference in Model.References)
            {
                <div class="review-entry">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    @reference.Email &bull; @reference.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@Model.CoverLetter</p>
        </section>

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-success" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public JobApplicationFormModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public Func<Task<int>> SubmitApplication { get; set; } = default!;

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        ErrorMessage = null;
        IsSubmitting = true;
        try
        {
            ApplicationId = await SubmitApplication();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

arguments.file_text:
@page "/apply"
@using sv_223a8a21b127483ba4ad363146c5d00d.Models
@using sv_223a8a21b127483ba4ad363146c5d00d.Services
@using sv_223a8a21b127483ba4ad363146c5d00d.Components.Pages.Apply

@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="formModel.Personal"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="formModel.WorkEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="formModel.References"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@formModel.CoverLetter"
                             CoverLetterChanged="UpdateCoverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Model="formModel"
                        OnBack="PreviousStep"
                        OnEditStep="NavigateToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep;
    private JobApplicationFormModel formModel = new();

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void NavigateToStep(int step) => currentStep = step;

    private void UpdateCoverLetter(string value)
    {
        formModel.CoverLetter = value;
    }

    private async Task<int> SubmitAsync()
    {
        var application = formModel.ToRecord();
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 720px;
    margin: 2rem auto;
    padding: 1.5rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-badge {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-badge {
    background: #4361ee;
    border-color: #4361ee;
    color: #fff;
}

.step-item.completed .step-badge {
    background: #2ec4b6;
    border-color: #2ec4b6;
    color: #fff;
}

.step-item.future .step-badge {
    background: #f0f0f0;
    border-color: #ddd;
    color: #aaa;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step-item.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #2ec4b6;
}

.step-item.future .step-label {
    color: #aaa;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
    transition: border-color 0.2s;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.15);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.35rem;
    font-size: 0.85rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.25rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s, opacity 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-success {
    background: #2ec4b6;
    color: #fff;
}

.btn-success:hover:not(:disabled) {
    background: #25a99d;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ccc;
    color: #555;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px solid #ddd;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #e63946;
    color: #fff;
}

.btn-danger:hover {
    background: #c5303c;
}

.btn-sm {
    padding: 0.3rem 0.7rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3651d4;
}

.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

/* Work Entry / Reference Forms */
.work-entry-form,
.reference-form {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    position: relative;
    background: #fafafa;
}

.work-entry-form legend,
.reference-form legend {
    font-weight: 600;
    font-size: 0.95rem;
    color: #333;
}

.remove-btn {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.35rem;
}

.character-count.over-limit {
    color: #e63946;
    font-weight: 600;
}

/* Review */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-data dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.4rem 0 0;
    font-size: 0.9rem;
    color: #555;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #333;
    margin: 0;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem 1rem;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #2ec4b6;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.confirmation h3 {
    color: #1a1a2e;
    margin-bottom: 0.5rem;
}

.confirmation p {
    color: #555;
}

/* Alert */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-danger {
    background: #fdecea;
    border: 1px solid #f5c6cb;
    color: #721c24;
}

