{"file_text": "@page "/apply"
@using sv_223a8a21b127483ba4ad363146c5d00d.Models
@using sv_223a8a21b127483ba4ad363146c5d00d.Services
@using sv_223a8a21b127483ba4ad363146c5d00d.Components.Pages.Apply

@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="formModel.Personal"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
            break;
        case 1:
            <WorkHistoryStep Entries="formModel.WorkEntries"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="formModel.References"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@formModel.CoverLetter"
                             CoverLetterChanged="UpdateCoverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Model="formModel"
                        OnBack="PreviousStep"
                        OnEditStep="NavigateToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int currentStep;
    private JobApplicationFormModel formModel = new();

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;
    private void NavigateToStep(int step) => currentStep = step;

    private void UpdateCoverLetter(string value)
    {
        formModel.CoverLetter = value;
    }

    private async Task<int> SubmitAsync()
    {
        var application = formModel.ToRecord();
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}
