.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-data dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-entry:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.4rem 0 0;
    font-size: 0.9rem;
    color: #555;
}

.review-cover-letter {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #333;
    margin: 0;
}

