.confirmation {
    text-align: center;
    padding: 2rem 1rem;
}

.confirmation-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #2ec4b6;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.confirmation h3 {
    color: #1a1a2e;
    margin-bottom: 0.5rem;
}

.confirmation p {
    color: #555;
}

/* Alert */
.alert {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.alert-danger {
    background: #fdecea;
    border: 1px solid #f5c6cb;
    color: #721c24;
}

